ALTER TABLE users ADD COLUMN age TINYINT UNSIGNED NULL, ADD COLUMN college VARCHAR(160) NOT NULL DEFAULT '', ADD COLUMN study_year VARCHAR(40) NOT NULL DEFAULT '', ADD COLUMN learning_goals VARCHAR(500) NOT NULL DEFAULT '', ADD COLUMN preferred_mode ENUM('Online','Campus','Either') NOT NULL DEFAULT 'Either', ADD COLUMN onboarded BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN is_demo BOOLEAN NOT NULL DEFAULT FALSE;
CREATE TABLE IF NOT EXISTS profile_media (id CHAR(48) PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, kind ENUM('avatar','document') NOT NULL, title VARCHAR(120) NOT NULL, mime VARCHAR(60) NOT NULL, content MEDIUMBLOB NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), INDEX(user_id,kind)) ENGINE=InnoDB;
